1	/**
2	 * Spline water ribbon — the traversable stream Benny rides from the Drum A drain to the towel.
3	 *
4	 * Geometry: rows every `ds` along the master course, columns across `widthAt(s)`; a slightly
5	 * concave trough with raised frothy edges plus a short skirt under each edge (thickness).
6	 * Shader: electric-cyan core with meandering hot-pink flow bands, advected white streaks and
7	 * sparkles (two-phase flow-map advection so per-stage speeds never shear), Fresnel/haze
8	 * reflection, specular glints, cellular soap-foam fringe, Benny ripple rings + V-wake, the five
9	 * glowing chevrons on the 04 slide, a dithered hand-over to the whirlpool surface in 03 and a
10	 * drain-away for the 11 outro.
11	 */
12	import * as THREE from 'three';
13	import type { Course, StageId } from '../world/course';
14	import { FRAG_TAIL, NOISE_GLSL, PALETTE, withFog } from './glsl';
15	
16	/** wave amplitude per stage (units); blended across boundaries */
17	const AMP: Partial<Record<StageId, number>> = {
18	  '02': 0.06, '03': 0.08, '04': 0.03, '05': 0.1, '06': 0.12, '07': 0.1, '08': 0.1, '09': 0.16, '10': 0.08, '11': 0.05,
19	};
20	export const EDGE_LIFT = 0.28;
21	
22	export function ampAt(course: Course, s: number): number {
23	  let v = 0, w = 0;
24	  for (const st of course.stages) {
25	    const a = smooth(st.s0 - 5, st.s0 + 5, s) * (1 - smooth(st.s1 - 5, st.s1 + 5, s));
26	    if (a > 0) { v += (AMP[st.id] ?? 0.08) * a; w += a; }
27	  }
28	  let amp = w > 0 ? v / w : 0.08;
29	  // calm the long straight of the deep plunge (fast sheet flow)
30	  const pt = course.marks['07_plunge_top'], pb = course.marks['07_plunge_bottom'];
31	  if (pt !== undefined) amp *= 1 - 0.6 * smooth(pt, pt + 8, s) * (1 - smooth(pb - 8, pb, s));
32	  return amp;
33	}
34	
35	function smooth(a: number, b: number, x: number) {
36	  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
37	  return t * t * (3 - 2 * t);
38	}
39	
40	/** CPU mirror of the vertex displacement (keep in sync with VERT). */
41	export function ribbonWave(u: number, s: number, t: number, amp: number): number {
42	  const au = Math.min(1, Math.abs(u));
43	  const trough = EDGE_LIFT * au * au * au;
44	  return trough + amp * (0.6 * Math.sin(s * 0.9 - t * 2.4 + u * 1.7) + 0.4 * Math.sin(s * 0.41 + t * 1.5 - u * 2.3));
45	}
46	
47	const VERT = /* glsl */ `
48	attribute vec2 aUV;      // x = u (-1..1 across), y = s (arc length)
49	attribute float aHalfW;
50	attribute float aSpeed;
51	attribute float aAmp;
52	attribute float aSkirt;  // 0 surface, 1 skirt bottom
53	uniform float uTime;
54	uniform vec4 uHide;      // s03Start, s04Start, chuteMark, unused
55	varying vec2 vUV;
56	varying float vHalfW;
57	varying float vSpeed;
58	varying float vSkirt;
59	varying float vHide;
60	varying vec3 vPosW;
61	varying vec3 vNormalW;
62	#include <fog_pars_vertex>
63	void main() {
64	  float u = aUV.x;
65	  float s = aUV.y;
66	  float h = aAmp * (0.6 * sin(s * 0.9 - uTime * 2.4 + u * 1.7) + 0.4 * sin(s * 0.41 + uTime * 1.5 - u * 2.3));
67	  vec3 p = position + normal * h * (1.0 - aSkirt);
68	  vec4 wp = modelMatrix * vec4(p, 1.0);
69	  vPosW = wp.xyz;
70	  vNormalW = normalize(mat3(modelMatrix) * normal);
71	  vUV = aUV;
72	  vHalfW = aHalfW;
73	  vSpeed = aSpeed;
74	  vSkirt = aSkirt;
75	  // hand the stream over to the whirlpool surface during 03 (dithered fade both ways)
76	  float inside03 = smoothstep(uHide.x + 0.5, uHide.x + 3.5, s) * (1.0 - smoothstep(uHide.y - 9.0, uHide.y - 1.5, s));
77	  vHide = 1.0 - inside03;
78	  vec4 mvPosition = viewMatrix * wp;
79	  gl_Position = projectionMatrix * mvPosition;
80	  #include <fog_vertex>
81	}
82	`;
83	
84	const FRAG = /* glsl */ `
85	uniform float uTime;
86	uniform vec3 uCyanDeep;
87	uniform vec3 uCyan;
88	uniform vec3 uCyanBright;
89	uniform vec3 uPink;
90	uniform vec3 uPinkLight;
91	uniform vec3 uFoam;
92	uniform vec3 uFoamLav;
93	uniform vec3 uHaze;
94	uniform vec3 uLightDir;
95	uniform vec3 uBenny;      // s, lateral (units), strength
96	uniform vec3 uChevron;    // start s, spacing, enabled
97	uniform vec2 uOutro;      // amount, chamber start s
98	varying vec2 vUV;
99	varying float vHalfW;
100	varying float vSpeed;
101	varying float vSkirt;
102	varying float vHide;
103	varying vec3 vPosW;
104	varying vec3 vNormalW;
105	#include <fog_pars_fragment>
106	${NOISE_GLSL}
107	
108	// one advected layer of the flow pattern
109	// returns: x = pink mask, y = white streaks, z = streak noise (shading), w = pink fine streaks
110	vec4 flowLayer(float u, float v) {
111	  float m = (vnoise(vec2(v * 0.07, 3.1)) - 0.5) * 0.9 + sin(v * 0.19) * 0.16;
112	  float core = 0.54 + 0.16 * (vnoise(vec2(v * 0.13, u * 1.3 + 7.0)) - 0.5);
113	  float pinkMask = smoothstep(core - 0.07, core + 0.07, abs(u - m * 0.55));
114	  #ifdef LOW_Q
115	  float sn = vnoise(vec2(u * 4.0 + m * 4.0, v * 0.28));
116	  #else
117	  float sn = fbm3(vec2(u * 4.0 + m * 4.0, v * 0.28));
118	  #endif
119	  // crisp, thin white highlight lines stretched along the flow
120	  float ln = vnoise(vec2(u * 15.0 + m * 6.0 + sn * 2.5, v * 0.33));
121	  float streak = smoothstep(0.8, 0.93, ln) * 1.5 + smoothstep(0.72, 0.8, sn) * 0.25;
122	  float fineP = smoothstep(0.7, 0.76, vnoise(vec2(u * 7.0 - m * 3.0, v * 0.21 + 11.0)));
123	  return vec4(pinkMask, streak, sn, fineP);
124	}
125	
126	void main() {
127	  float u = vUV.x;
128	  float s = vUV.y;
129	  // dithered hide (03 hand-over)
130	  if (vHide < 0.5) discard;
131	  float cutFoam = 1.0 - smoothstep(0.5, 0.85, vHide);
132	  // 11 outro: the stream drains away in the chamber, leaving puddles
133	  if (uOutro.x > 0.0 && s > uOutro.y - 2.0) {
134	    float n = vnoise(vec2(u * 3.0, s * 0.35)) * 0.7 + 0.3;
135	    if (n < uOutro.x * 1.15) discard;
136	  }
137	
138	  // two-phase flow-map advection (period 4 s); offset scales with the local stage speed
139	  float ph0 = fract(uTime * 0.25);
140	  float ph1 = fract(uTime * 0.25 + 0.5);
141	  float w0 = 1.0 - abs(1.0 - 2.0 * ph0);
142	  vec4 A = flowLayer(u, s - vSpeed * ph0 * 4.0);
143	  vec4 B = flowLayer(u, s - vSpeed * ph1 * 4.0 + 23.0);
144	  vec4 F = mix(B, A, w0);
145	  // fine detail layer (single phase, short period) so close-up water keeps crisp streaks
146	  float fineV = s - vSpeed * fract(uTime * 0.5) * 2.0;
147	  float fine = vnoise(vec2(u * 34.0 + F.z * 4.0, fineV * 1.1));
148	  float fineW = vnoise(vec2(u * 34.0 + F.z * 4.0, (fineV + vSpeed) * 1.1));
149	  fine = mix(fineW, fine, 1.0 - abs(1.0 - 2.0 * fract(uTime * 0.5)));
150	  F.y += smoothstep(0.84, 0.95, fine) * 0.9;
151	  F.z = clamp(F.z + (fine - 0.5) * 0.18, 0.0, 1.0);
152	
153	  vec3 cyanCol = mix(uCyanDeep, uCyan, smoothstep(0.22, 0.62, F.z));
154	  cyanCol = mix(cyanCol, uCyanBright, smoothstep(0.6, 0.82, F.z) * 0.7);
155	  vec3 pinkCol = mix(uPink, uPinkLight, F.z * 0.7);
156	  float pinkM = clamp(F.x + F.w * 0.8, 0.0, 1.0);
157	  vec3 col = mix(cyanCol, pinkCol, pinkM);
158	
159	  // perturbed normal from the streak noise for glossy highlights
160	  float e = 0.02;
161	  vec3 N = normalize(vNormalW + 0.35 * vec3(F.z - 0.5, 0.0, F.y * 0.3 - 0.15));
162	  vec3 V = normalize(cameraPosition - vPosW);
163	  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.0);
164	  vec3 R = reflect(-V, N);
165	  vec3 refl = mix(uHaze, vec3(1.0), smoothstep(0.1, 0.9, R.y));
166	  col = mix(col, refl, fres * 0.2);
167	  vec3 H = normalize(normalize(uLightDir) + V);
168	  float spec = pow(clamp(dot(N, H), 0.0, 1.0), 80.0);
169	  col += vec3(1.0) * (spec * 1.4 + F.y * 0.9);
170	
171	  // twinkling sparkles
172	  vec2 g = vec2(u * 9.0, (s - vSpeed * uTime * 0.6) * 1.6);
173	  vec2 gi = floor(g);
174	  float hs = hash12(gi);
175	  vec2 gf = fract(g) - 0.5;
176	  float tw = 0.5 + 0.5 * sin(uTime * 7.0 + hs * 40.0);
177	  float sparkle = step(0.93, hs) * smoothstep(0.18, 0.0, length(gf)) * tw;
178	  col += vec3(1.2) * sparkle;
179	
180	  // soap-foam fringe along the edges
181	  float edgeN = (vnoise(vec2(s * 1.3, u * 2.0)) - 0.5) * 0.16;
182	  float edge = smoothstep(0.86, 0.97, abs(u) + edgeN);
183	  float c = cells(vec2(u * vHalfW * 4.0, (s - vSpeed * uTime * 0.5) * 3.6));
184	  vec3 foamCol = mix(uFoam * 1.2, uFoamLav * 0.8, smoothstep(0.2, 0.7, c));
185	  col = mix(col, foamCol, edge * smoothstep(0.08, 0.35, c + 0.15));
186	  col = mix(col, uFoamLav * 0.92, vSkirt);
187	  col = mix(col, foamCol, cutFoam);
188	
189	  // Benny: ripple rings around him + V wake behind
190	  if (uBenny.z > 0.0) {
191	    float du = u * vHalfW - uBenny.y;
192	    float dv = s - uBenny.x;
193	    float d = length(vec2(du, dv * 0.8));
194	    float rings = smoothstep(0.55, 1.0, 0.5 + 0.5 * sin(d * 5.5 - uTime * 9.0)) * exp(-d * 0.7) * smoothstep(0.75, 1.05, d);
195	    float back = clamp(-dv, 0.0, 30.0);
196	    float wakeV = exp(-abs(abs(du) - back * 0.42 - 0.7) * 3.5) * exp(-back * 0.16) * step(dv, 0.0);
197	    col = mix(col, uFoam, clamp((rings * 0.75 + wakeV * 0.85) * uBenny.z, 0.0, 1.0));
198	  }
199	
200	  // 04: exactly five glowing chevrons pointing downhill (direction of travel)
201	  if (uChevron.z > 0.5) {
202	    float x = u * vHalfW;
203	    for (int k = 0; k < 5; k++) {
204	      float y = s - (uChevron.x + float(k) * uChevron.y);
205	      if (abs(y) < 2.4 && abs(x) < 1.6) {
206	        // "^" pointing toward +s: tip at y=+1.0, arms sweep back 1.9 units over ±1.15 lateral
207	        float dist = abs(y - (1.0 - abs(x) * 1.65)) * 0.52;
208	        float arm = smoothstep(1.2, 1.1, abs(x));
209	        float core = smoothstep(0.2, 0.11, dist) * arm;
210	        float halo = smoothstep(0.7, 0.0, dist) * smoothstep(1.5, 0.9, abs(x)) * 0.5;
211	        col = mix(col, vec3(1.0), clamp(halo, 0.0, 1.0));
212	        col = mix(col, vec3(2.2, 2.4, 2.5), core);
213	      }
214	    }
215	  }
216	  gl_FragColor = vec4(col, 1.0);
217	  ${FRAG_TAIL}
218	}
219	`;
220	
221	export interface Ribbon {
222	  mesh: THREE.Mesh;
223	  uniforms: Record<string, THREE.IUniform>;
224	  s0: number;
225	  s1: number;
226	  heightAt(s: number, lateral: number, t: number): number;
227	}
228	
229	export function createRibbon(course: Course, opts: { s0: number; s1: number; quality: 'high' | 'low' }): Ribbon {
230	  const { s0, s1, quality } = opts;
231	  const ds = quality === 'high' ? 0.4 : 0.7;
232	  const cols = quality === 'high' ? 18 : 10;
233	  const rows = Math.ceil((s1 - s0) / ds) + 1;
234	  const vertsPerRow = cols + 1 + 2; // + skirt left/right
235	  const n = rows * vertsPerRow;
236	  const pos = new Float32Array(n * 3);
237	  const nor = new Float32Array(n * 3);
238	  const uv = new Float32Array(n * 2);
239	  const halfW = new Float32Array(n);
240	  const speed = new Float32Array(n);
241	  const amp = new Float32Array(n);
242	  const skirt = new Float32Array(n);
243	  const tmp = new THREE.Vector3();
244	  const nrm = new THREE.Vector3();
245	  let k = 0;
246	  for (let i = 0; i < rows; i++) {
247	    const s = Math.min(s1, s0 + i * ds);
248	    const f = course.sample(s);
249	    const hw = course.widthAt(s) / 2;
250	    const sp = Math.max(3, course.prop(s, 'speed'));
251	    const a = ampAt(course, s);
252	    const put = (u: number, lateral: number, h: number, isSkirt: number, nn: THREE.Vector3) => {
253	      tmp.copy(f.pos).addScaledVector(f.right, lateral).addScaledVector(f.up, h);
254	      tmp.toArray(pos, k * 3);
255	      nn.toArray(nor, k * 3);
256	      uv[k * 2] = u;
257	      uv[k * 2 + 1] = s;
258	      halfW[k] = hw;
259	      speed[k] = sp;
260	      amp[k] = a;
261	      skirt[k] = isSkirt;
262	      k++;
263	    };
264	    // left skirt (below left edge)
265	    put(-1, -hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right).negate());
266	    for (let j = 0; j <= cols; j++) {
267	      const u = -1 + (2 * j) / cols;
268	      const lift = EDGE_LIFT * Math.abs(u) ** 3;
269	      const slope = (EDGE_LIFT * 3 * u * Math.abs(u)) / hw; // d lift / d lateral
270	      nrm.copy(f.up).addScaledVector(f.right, -slope).normalize();
271	      put(u, u * hw, lift, 0, nrm);
272	    }
273	    put(1, hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right));
274	  }
275	  const idx: number[] = [];
276	  for (let i = 0; i < rows - 1; i++) {
277	    for (let j = 0; j < vertsPerRow - 1; j++) {
278	      const a = i * vertsPerRow + j, b = a + 1, c = a + vertsPerRow, d = c + 1;
279	      idx.push(a, c, b, b, c, d);
280	    }
281	  }
282	  const geo = new THREE.BufferGeometry();
283	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
284	  geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
285	  geo.setAttribute('aUV', new THREE.BufferAttribute(uv, 2));
286	  geo.setAttribute('aHalfW', new THREE.BufferAttribute(halfW, 1));
287	  geo.setAttribute('aSpeed', new THREE.BufferAttribute(speed, 1));
288	  geo.setAttribute('aAmp', new THREE.BufferAttribute(amp, 1));
289	  geo.setAttribute('aSkirt', new THREE.BufferAttribute(skirt, 1));
290	  geo.setIndex(idx);
291	  geo.computeBoundingSphere();
292	
293	  const st03 = course.stage('03'), st04 = course.stage('04'), st08 = course.stage('08');
294	  const uniforms = withFog({
295	    uTime: { value: 0 },
296	    uCyanDeep: { value: PALETTE.cyanDeep.clone() },
297	    uCyan: { value: PALETTE.cyan.clone() },
298	    uCyanBright: { value: PALETTE.cyanBright.clone() },
299	    uPink: { value: PALETTE.pink.clone() },
300	    uPinkLight: { value: PALETTE.pinkLight.clone() },
301	    uFoam: { value: PALETTE.foam.clone() },
302	    uFoamLav: { value: PALETTE.foamLav.clone() },
303	    uHaze: { value: PALETTE.haze.clone() },
304	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
305	    uBenny: { value: new THREE.Vector3(0, 0, 0) },
306	    uChevron: { value: new THREE.Vector3(st04.s0 + 8.5, 3.6, 1) },
307	    uOutro: { value: new THREE.Vector2(0, st08.s0) },
308	    uHide: { value: new THREE.Vector4(st03.s0, st04.s0, 0, 0) },
309	  });
310	  const mat = new THREE.ShaderMaterial({
311	    uniforms,
312	    vertexShader: VERT,
313	    fragmentShader: FRAG,
314	    fog: true,
315	    side: THREE.DoubleSide,
316	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
317	  });
318	  const mesh = new THREE.Mesh(geo, mat);
319	  mesh.name = 'water_ribbon';
320	  mesh.frustumCulled = false; // one long mesh spanning the whole course
321	  return {
322	    mesh,
323	    uniforms,
324	    s0,
325	    s1,
326	    heightAt(s, lateral, t) {
327	      const hw = course.widthAt(s) / 2;
328	      return ribbonWave(lateral / hw, s, t, ampAt(course, s));
329	    },
330	  };
331	}
332

1	/**
2	 * Rainbow water system (water-fx-specialist + foam-bubbles-particles).
3	 *
4	 *   const water = createWater(course, { quality: 'high' });
5	 *   scene.add(water.group);
6	 *   // per frame:
7	 *   water.update(time, dt, bennyS, camera);
8	 *   water.wake(bennyPos, forward, right, speed, dt);
9	 *   // cinematic controls (0..1): water.controls.drumSwirl / drumAgitation / outro
10	 *
11	 * Benny rides ON the water: place his body centre at
12	 *   course.pointAt(s, lateral, water.surfaceHeight(s, lateral, time) + BENNY_RIDE_OFFSET)
13	 * (BENNY_RIDE_OFFSET ≈ 0.55 for a 0.8-radius body: bottom third in the water, splash visible).
14	 */
15	import * as THREE from 'three';
16	import { type Course, WORLD, funnelY } from '../world/course';
17	import { createRibbon } from './waterRibbon';
18	import { createWhirlpool, whirlpoolHeight, FUNNEL_LIFT } from './whirlpool';
19	import { createDrumWater } from './drumWater';
20	import { createFinalWave } from './finalWave';
21	import { createPuddles } from './puddles';
22	import { createFoam } from './foam';
23	import { createBubbles } from './bubbles';
24	import { createSpray } from './spray';
25	
26	export { PALETTE } from './glsl';
27	export const BENNY_RIDE_OFFSET = 0.55;
28	
29	export interface WaterControls {
30	  /** 02 tumble: spinning water shell on the Drum A wall (0..1) */
31	  drumSwirl: number;
32	  /** Drum A swell size: 0 calm (01) .. 1 spin cycle (02) */
33	  drumAgitation: number;
34	  /** 11 outro: stream drains away (0..1) and leftover puddles appear */
35	  outro: number;
36	}
37	
38	export interface WaterSystem {
39	  group: THREE.Group;
40	  /** call every frame; focusS = Benny's arc-length (for pooling/LOD of bubbles & foam) */
41	  update(time: number, dt: number, focusS: number, camera: THREE.Camera): void;
42	  /** height of the animated water surface above the course centreline frame at (s, lateral) */
43	  surfaceHeight(s: number, lateral: number, time: number): number;
44	  /** spray/wake at Benny: call each frame while riding */
45	  wake(pos: THREE.Vector3, forward: THREE.Vector3, right: THREE.Vector3, speed: number, dt: number): void;
46	  splash(pos: THREE.Vector3, up: THREE.Vector3, strength: number): void;
47	  /** cinematic controls */
48	  controls: WaterControls;
49	  /** sub-systems (for visibility overrides / debugging) */
50	  parts: Record<string, THREE.Object3D>;
51	  /** live stats for perf reporting */
52	  stats(): { instances: number; bubbles: number; smallBubbles: number; sprayCapacity: number };
53	}
54	
55	const smooth = (a: number, b: number, x: number) => {
56	  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
57	  return t * t * (3 - 2 * t);
58	};
59	
60	export function createWater(course: Course, opts: { quality?: 'high' | 'low' } = {}): WaterSystem {
61	  const quality = opts.quality ?? 'high';
62	  const group = new THREE.Group();
63	  group.name = 'water_system';
64	
65	  const drainMark = course.marks['02_drain'] ?? course.stage('02').s1 - 2;
66	  const st03 = course.stage('03'), st04 = course.stage('04'), st08 = course.stage('08'), st09 = course.stage('09');
67	  const ribbonS0 = drainMark - 1;
68	  const ribbon = createRibbon(course, { s0: ribbonS0, s1: course.length, quality });
69	  // open the funnel where the 04 slide tube leaves the basin (the course exits the spiral at
70	  // r≈2.8, just outside the drain hole, and the slide then runs beneath the funnel surface)
71	  const cutPts: THREE.Vector3[] = [];
72	  for (let i = 0; i < 8; i++) {
73	    const s = st04.s0 - 3 + (i / 7) * 34;
74	    const f = course.sample(s);
75	    cutPts.push(f.pos.clone().addScaledVector(f.up, 1.2));
76	  }
77	  const whirl = createWhirlpool(quality, { points: cutPts, radius: Math.max(3.6, course.stage('04').tube * 0.85) });
78	  const drum = createDrumWater(quality);
79	  const wave = createFinalWave(course, quality);
80	  const puddles = createPuddles();
81	  const foam = createFoam(course, { s0: ribbonS0, s1: course.length, quality });
82	  const bubbles = createBubbles(course, { quality, sStart: ribbonS0 });
83	  const spray = createSpray(quality);
84	  group.add(ribbon.mesh, whirl.mesh, drum.group, wave.mesh, puddles.group, foam.group, bubbles.group, spray.points);
85	
86	  const controls: WaterControls = { drumSwirl: 0, drumAgitation: 0, outro: 0 };
87	  let focus = 0;
88	  let curTime = 0;
89	  const tmpV = new THREE.Vector3();
90	  const tmpV2 = new THREE.Vector3();
91	  const rnd = (a: number, b: number) => a + Math.random() * (b - a);
92	
93	  /** 0 = ribbon fully shown, 1 = whirlpool surface takes over (mirrors the ribbon vertex shader) */
94	  const whirlBlend = (s: number) => smooth(st03.s0 + 0.5, st03.s0 + 3.5, s) * (1 - smooth(st04.s0 - 9, st04.s0 - 1.5, s));
95	
96	  const surfaceHeight = (s: number, lateral: number, t: number): number => {
97	    if (s < ribbonS0) {
98	      // Drum A: absolute swell height relative to the course point
99	      const p = course.pointAt(s, lateral, 0, tmpV);
100	      const up = course.sample(s).up;
101	      return (drum.heightAt(p.x, p.z, t) - p.y) / Math.max(0.3, up.y);
102	    }
103	    const hr = ribbon.heightAt(s, lateral, t);
104	    const k = whirlBlend(s);
105	    if (k <= 0) return hr;
106	    const f = course.sample(s);
107	    const p = tmpV.copy(f.pos).addScaledVector(f.right, lateral);
108	    const b = WORLD.basin;
109	    const r = Math.hypot(p.x - b.center.x, p.z - b.center.z);
110	    const yW = funnelY(r) + FUNNEL_LIFT + whirlpoolHeight(p.x, p.z, t);
111	    const hw = (yW - p.y) / Math.max(0.3, f.up.y);
112	    return hr * (1 - k) + hw * k;
113	  };
114	
115	  return {
116	    group,
117	    controls,
118	    parts: { ribbon: ribbon.mesh, whirlpool: whirl.mesh, drum: drum.group, drumSwirl: drum.swirl, finalWave: wave.mesh, puddles: puddles.group, foam: foam.group, bubbles: bubbles.group, spray: spray.points },
119	    surfaceHeight,
120	    stats: () => ({ instances: foam.instanceCount, bubbles: bubbles.counts.big, smallBubbles: bubbles.counts.small, sprayCapacity: spray.capacity }),
121	    update(time, dt, focusS, camera) {
122	      focus = focusS;
123	      curTime = time;
124	      ribbon.uniforms.uTime.value = time;
125	      whirl.uniforms.uTime.value = time;
126	      drum.uniforms.uTime.value = time;
127	      drum.uniforms.uAgitation.value = controls.drumAgitation;
128	      drum.swirlUniforms.uSwirl.value = controls.drumSwirl;
129	      drum.swirl.visible = controls.drumSwirl > 0.001;
130	      wave.uniforms.uTime.value = time;
131	      puddles.uniforms.uTime.value = time;
132	      puddles.uniforms.uAmount.value = controls.outro;
133	      (ribbon.uniforms.uOutro.value as THREE.Vector2).x = controls.outro;
134	      puddles.group.visible = controls.outro > 0.001;
135	      // region visibility (perf): only what the camera around focusS can see
136	      drum.group.visible = focusS < st03.s0 + 12;
137	      whirl.mesh.visible = focusS > drainMark - 8 && focusS < st04.s0 + 45;
138	      wave.mesh.visible = focusS > st08.s0 - 25;
139	      // when Benny is off the ribbon (drum / whirlpool), no ribbon wake
140	      if (focusS < ribbonS0 || whirlBlend(focusS) > 0.5) (ribbon.uniforms.uBenny.value as THREE.Vector3).z = 0;
141	      foam.update(time, focusS, controls.outro);
142	      bubbles.update(time, dt, focusS, camera, 1 - 0.7 * controls.outro);
143	      // crest spray off the final wave
144	      if (wave.mesh.visible && focusS > st09.s0 - 20 && focusS < st09.s1 + 20 && controls.outro < 0.5) {
145	        const n = quality === 'high' ? 3 : 1;
146	        for (let i = 0; i < n; i++) {
147	          const c = wave.crest[(Math.random() * wave.crest.length) | 0];
148	          if (!c) break;
149	          const f = course.sample(Math.min(course.length, Math.max(0, focusS)));
150	          tmpV2.copy(f.right).multiplyScalar(rnd(1, 3.5)).addScaledVector(f.up, rnd(1.5, 4)).addScaledVector(f.tan, rnd(-1, 2));
151	          spray.emit(c, tmpV2, rnd(0.08, 0.2), rnd(0.5, 1.0));
152	        }
153	      }
154	      spray.update(dt, camera);
155	    },
156	    wake(pos, forward, right, speed, dt) {
157	      const s = focus;
158	      if (s >= ribbonS0 && whirlBlend(s) < 0.5) {
159	        const f = course.sample(s);
160	        const lateral = tmpV.copy(pos).sub(f.pos).dot(f.right);
161	        (ribbon.uniforms.uBenny.value as THREE.Vector3).set(s, lateral, Math.min(1, speed / 8));
162	      }
163	      // side fans of droplets (refs 05/07/08/10)
164	      const rate = speed * (quality === 'high' ? 5 : 2);
165	      const n = Math.floor(rate * dt + Math.random());
166	      const up = tmpV2.crossVectors(right, forward).normalize();
167	      for (let i = 0; i < n; i++) {
168	        const side = Math.random() < 0.5 ? -1 : 1;
169	        const p = pos.clone().addScaledVector(right, side * rnd(0.55, 0.85)).addScaledVector(forward, rnd(-0.4, 0.2)).addScaledVector(up, rnd(-0.45, -0.2));
170	        const v = right.clone().multiplyScalar(side * rnd(1.2, 3.2)).addScaledVector(up, rnd(2.0, 4.5)).addScaledVector(forward, rnd(-1.5, 1.0));
171	        spray.emit(p, v, rnd(0.06, 0.16), rnd(0.35, 0.7));
172	      }
173	      void curTime;
174	    },
175	    splash(pos, up, strength) {
176	      const n = Math.round(30 * strength * (quality === 'high' ? 1 : 0.5));
177	      for (let i = 0; i < n; i++) {
178	        const dir = new THREE.Vector3(rnd(-1, 1), 0, rnd(-1, 1)).normalize().multiplyScalar(rnd(1, 4) * strength);
179	        dir.addScaledVector(up, rnd(3, 7) * strength);
180	        spray.emit(pos, dir, rnd(0.08, 0.22), rnd(0.5, 1.1));
181	      }
182	    },
183	  };
184	}
