1	/** Shared GLSL snippets for Rainbow water/foam/bubble shaders (WebGL2, mobile-safe). */
2	import * as THREE from 'three';
3	
4	export const NOISE_GLSL = /* glsl */ `
5	float hash12(vec2 p) {
6	  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
7	  p3 += dot(p3, p3.yzx + 33.33);
8	  return fract((p3.x + p3.y) * p3.z);
9	}
10	float vnoise(vec2 p) {
11	  vec2 i = floor(p);
12	  vec2 f = fract(p);
13	  vec2 u = f * f * (3.0 - 2.0 * f);
14	  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
15	             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
16	}
17	float fbm3(vec2 p) {
18	  float a = 0.5, s = 0.0;
19	  for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }
20	  return s;
21	}
22	// cheap cellular "soap foam" pattern: 0 at cell centres -> 1 at borders
23	float cells(vec2 p) {
24	  vec2 i = floor(p);
25	  vec2 f = fract(p);
26	  float md = 8.0;
27	  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
28	    vec2 g = vec2(float(x), float(y));
29	    vec2 o = vec2(hash12(i + g), hash12(i + g + 19.7));
30	    vec2 r = g + o - f;
31	    md = min(md, dot(r, r));
32	  }
33	  return sqrt(md);
34	}
35	vec3 iridescent(float t) {
36	  return 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.0, 0.33, 0.67)));
37	}
38	`;
39	
40	/**
41	 * Rainbow water palette (sRGB hex → linear THREE.Color, ready for uniforms).
42	 * Base hues are scaled below the NeutralToneMapping knee (~0.76 linear) so the renderer does not
43	 * desaturate them toward pastel; only highlights/sparkles/foam exceed 1.0 (and feed bloom).
44	 */
45	const knee = (hex: string, k = 0.74) => new THREE.Color(hex).multiplyScalar(k);
46	export const PALETTE = {
47	  cyanDeep: knee('#0080e8', 0.72),
48	  cyan: knee('#08c0ff'),
49	  cyanBright: knee('#56f0ff', 0.8),
50	  pink: knee('#ff149f'),
51	  pinkLight: knee('#ff4cc0', 0.78),
52	  magenta: new THREE.Color('#e01ea0'),
53	  foam: new THREE.Color('#ffffff'),
54	  foamLav: new THREE.Color('#efe2ff'),
55	  haze: new THREE.Color('#ffd6f4'),
56	};
57	
58	/** fog-aware uniforms merged into every water ShaderMaterial */
59	export function withFog<T extends Record<string, THREE.IUniform>>(u: T): T & typeof THREE.UniformsLib.fog {
60	  return THREE.UniformsUtils.merge([THREE.UniformsLib.fog, u]) as T & typeof THREE.UniformsLib.fog;
61	}
62	
63	/** standard tail: tonemapping + colour space + fog (call with gl_FragColor already set) */
64	export const FRAG_TAIL = /* glsl */ `
65	  #include <tonemapping_fragment>
66	  #include <colorspace_fragment>
67	  #include <fog_fragment>
68	`;
