1	/**
2	 * Foam banks: instanced puffy white/lavender soap-foam clusters.
3	 *  - a dense fringe of small puffs along both ribbon edges + bigger cloud clusters (refs 03–10)
4	 *  - foam rings on the whirlpool rim and along its spiral bands (rotating with the swirl)
5	 * Puffs are grouped into ~40-unit chunks (separate InstancedMeshes) so only chunks near Benny
6	 * are drawn; quality 'low' halves density and uses 20-tri puffs.
7	 */
8	import * as THREE from 'three';
9	import { type Course, WORLD, funnelY } from '../world/course';
10	import { EDGE_LIFT } from './waterRibbon';
11	import { SPIRAL_C, FUNNEL_LIFT } from './whirlpool';
12	
13	interface Puff { p: THREE.Vector3; r: number; c: number }
14	
15	function rng(seed: number) {
16	  let a = seed >>> 0;
17	  return () => {
18	    a = (a + 0x6d2b79f5) >>> 0;
19	    let t = a;
20	    t = Math.imul(t ^ (t >>> 15), t | 1);
21	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
22	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
23	  };
24	}
25	
26	const FOAM_COLORS = ['#ffffff', '#f6f0ff', '#efe4ff', '#fff2fb', '#e9f6ff'].map((c) => new THREE.Color(c));
27	
28	function makeMaterial() {
29	  const m = new THREE.MeshStandardMaterial({
30	    color: '#ffffff',
31	    roughness: 0.32,
32	    metalness: 0.0,
33	    emissive: new THREE.Color('#ece4ff'),
34	    emissiveIntensity: 0.62,
35	    envMapIntensity: 1.1,
36	  });
37	  // subtle soap-film rim tint
38	  m.onBeforeCompile = (sh) => {
39	    sh.fragmentShader = sh.fragmentShader.replace(
40	      '#include <emissivemap_fragment>',
41	      `#include <emissivemap_fragment>
42	       float rimF = pow(1.0 - clamp(dot(normalize(vNormal), normalize(vViewPosition)), 0.0, 1.0), 2.5);
43	       totalEmissiveRadiance += vec3(0.55, 0.35, 0.75) * rimF * 0.35;`,
44	    );
45	  };
46	  return m;
47	}
48	
49	export interface FoamSystem {
50	  group: THREE.Group;
51	  whirlGroup: THREE.Group;
52	  update(time: number, focusS: number, outro?: number): void;
53	  instanceCount: number;
54	}
55	
56	export function createFoam(course: Course, opts: { s0: number; s1: number; quality: 'high' | 'low' }): FoamSystem {
57	  const { s0, s1, quality } = opts;
58	  const rand = rng(1337);
59	  const density = quality === 'high' ? 1 : 0.5;
60	  const geo = new THREE.IcosahedronGeometry(1, quality === 'high' ? 1 : 0);
61	  const mat = makeMaterial();
62	  const group = new THREE.Group();
63	  group.name = 'foam_banks';
64	  const st03 = course.stage('03'), st04 = course.stage('04');
65	  const chunkLen = 40;
66	  const chunks: { mesh: THREE.InstancedMesh; sa: number; sb: number }[] = [];
67	  let total = 0;
68	  const tmpM = new THREE.Matrix4();
69	  const tmpQ = new THREE.Quaternion();
70	  const tmpS = new THREE.Vector3();
71	
72	  const build = (list: Puff[], parent: THREE.Object3D, sa: number, sb: number) => {
73	    if (!list.length) return;
74	    const mesh = new THREE.InstancedMesh(geo, mat, list.length);
75	    list.forEach((pf, i) => {
76	      tmpQ.setFromEuler(new THREE.Euler(rand() * 6, rand() * 6, rand() * 6));
77	      tmpS.set(pf.r, pf.r * (0.75 + rand() * 0.25), pf.r);
78	      tmpM.compose(pf.p, tmpQ, tmpS);
79	      mesh.setMatrixAt(i, tmpM);
80	      mesh.setColorAt(i, FOAM_COLORS[pf.c % FOAM_COLORS.length]);
81	    });
82	    mesh.instanceMatrix.needsUpdate = true;
83	    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
84	    mesh.computeBoundingSphere();
85	    parent.add(mesh);
86	    chunks.push({ mesh, sa, sb });
87	    total += list.length;
88	  };
89	
90	  // ---- ribbon edges ----
91	  for (let sa = s0; sa < s1; sa += chunkLen) {
92	    const sb = Math.min(s1, sa + chunkLen);
93	    const list: Puff[] = [];
94	    // skip most of 03 (the whirlpool has its own foam), keep the chute→rim hand-over
95	    for (let s = sa; s < sb; s += 0.55 / density) {
96	      if (s > st03.s0 + 4 && s < st04.s0 - 6) continue;
97	      const f = course.sample(s);
98	      const hw = course.widthAt(s) / 2;
99	      const tube = course.prop(s, 'tube');
100	      for (const side of [-1, 1]) {
101	        if (rand() < 0.15) continue;
102	        const lat = side * (hw - 0.12 + rand() * 0.55);
103	        const r = 0.14 + rand() * 0.22;
104	        const p = f.pos.clone().addScaledVector(f.right, lat).addScaledVector(f.up, EDGE_LIFT + r * 0.25 + rand() * 0.1);
105	        list.push({ p, r, c: (rand() * 5) | 0 });
106	      }
107	      // cloud clusters
108	      if (rand() < 0.07 * density) {
109	        const side = rand() < 0.5 ? -1 : 1;
110	        const maxOut = tube > 0 ? Math.max(0.6, tube * 0.85 - hw) : 2.4;
111	        const cl = side * (hw + 0.4 + rand() * Math.min(1.4, maxOut));
112	        const n = 7 + ((rand() * 12) | 0);
113	        for (let k = 0; k < n; k++) {
114	          const ds = (rand() - 0.5) * 3.2;
115	          const f2 = course.sample(Math.min(s1, Math.max(s0, s + ds)));
116	          const lat = cl + (rand() - 0.5) * 1.8;
117	          const r = 0.18 + rand() * 0.34;
118	          const h = EDGE_LIFT * 0.6 + rand() * 0.9 * (1 - Math.abs(ds) / 2);
119	          const p = f2.pos.clone().addScaledVector(f2.right, lat).addScaledVector(f2.up, h);
120	          list.push({ p, r, c: (rand() * 5) | 0 });
121	        }
122	      }
123	    }
124	    build(list, group, sa - 6, sb + 6);
125	  }
126	
127	  // ---- whirlpool: rim ring + spiral band foam (rotates with the swirl) ----
128	  const whirlGroup = new THREE.Group();
129	  whirlGroup.name = 'foam_whirlpool';
130	  const b = WORLD.basin;
131	  whirlGroup.position.set(b.center.x, 0, b.center.z);
132	  const wl: Puff[] = [];
133	  // rim: cloud clusters of soap foam with a thin continuous fringe between them
134	  const nClusters = Math.round(26 * density);
135	  for (let k = 0; k < nClusters; k++) {
136	    const th0 = rand() * Math.PI * 2;
137	    const n = 10 + ((rand() * 16) | 0);
138	    for (let i = 0; i < n; i++) {
139	      const th = th0 + (rand() - 0.5) * 0.35;
140	      const r = b.rimRadius - 0.7 + (rand() - 0.4) * 1.3;
141	      const sz = 0.18 + rand() * 0.42;
142	      wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.35 + rand() * 0.55, r * Math.cos(th)), r: sz, c: (rand() * 5) | 0 });
143	    }
144	  }
145	  const nRim = Math.round(200 * density);
146	  for (let i = 0; i < nRim; i++) {
147	    const th = rand() * Math.PI * 2;
148	    const r = b.rimRadius - 0.4 + (rand() - 0.5) * 0.6;
149	    const sz = 0.1 + rand() * 0.18;
150	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, c: (rand() * 5) | 0 });
151	  }
152	  // along 3 spiral flow lines (constant th - C ln r) to echo the white foam bands
153	  const nBand = Math.round(60 * density);
154	  for (let i = 0; i < nBand; i++) {
155	    const band = ((i % 3) * Math.PI * 2) / 3 + 0.4;
156	    const r = 3.0 + rand() * (b.rimRadius - 3.6);
157	    const th = band + SPIRAL_C * Math.log(r) + (rand() - 0.5) * 0.12;
158	    const sz = 0.07 + rand() * 0.13;
159	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, c: (rand() * 5) | 0 });
160	  }
161	  const whirlStart = chunks.length;
162	  build(wl, whirlGroup, st03.s0 - 30, st04.s0 + 25);
163	  group.add(whirlGroup);
164	
165	  return {
166	    group,
167	    whirlGroup,
168	    instanceCount: total,
169	    update(time, focusS, outro = 0) {
170	      const s08 = course.stage('08').s0;
171	      for (let i = 0; i < chunks.length; i++) {
172	        const c = chunks[i];
173	        c.mesh.visible = c.sb > focusS - 25 && c.sa < focusS + 140 && !(outro > 0.3 && c.sb > s08 + 8);
174	      }
175	      // rotate whirlpool foam about the basin axis with the swirl (θ decreasing = course direction)
176	      whirlGroup.rotation.y = -time * 0.45 * ((Math.PI * 2) / 3);
177	      void whirlStart;
178	    },
179	  };
180	}
